<template>
  <div class="page-container gpm-page">
    <div class="page-head"><div><h2>农事服务管理</h2><p>统一管理技术指导、农机服务和灾害防范服务，支持定向推送。</p></div><el-button type="primary" @click="openEdit()">新增服务</el-button></div>
    <div class="panel"><el-form :inline="true" class="filters"><el-form-item label="关键字"><el-input v-model="filters.keyword" clearable placeholder="标题/区域/作物" /></el-form-item><el-form-item label="类型"><el-select v-model="filters.type" clearable placeholder="全部" style="width:140px"><el-option label="技术指导" value="技术指导"/><el-option label="农机服务" value="农机服务"/><el-option label="灾害防范" value="灾害防范"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" clearable placeholder="全部" style="width:130px"><el-option label="待发布" value="待发布"/><el-option label="已发布" value="已发布"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="reset">重置</el-button></el-form><el-table :data="rows" stripe><el-table-column prop="title" label="服务标题" min-width="220"/><el-table-column prop="type" label="类型" width="110"/><el-table-column prop="crop" label="作物" width="90"/><el-table-column prop="regionName" label="服务区域" width="110"/><el-table-column prop="provider" label="提供单位" min-width="180"/><el-table-column prop="status" label="状态" width="90"><template #default="{row}"><el-tag :type="row.status === '已发布' ? 'success' : 'warning'">{{ row.status }}</el-tag></template></el-table-column><el-table-column prop="pushCount" label="已推送" width="90"/><el-table-column label="操作" width="220"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button link type="success" @click="publish(row)">{{ row.status === '已发布' ? '撤回' : '发布' }}</el-button><el-button link @click="openPush(row)" :disabled="row.status !== '已发布'">定向推送</el-button></template></el-table-column></el-table></div>
    <el-dialog v-model="visible" :title="form.id ? '编辑农事服务' : '新增农事服务'" width="560px"><el-form ref="formRef" :model="form" :rules="formRules" label-width="90px"><el-form-item label="服务标题" prop="title"><el-input v-model="form.title"/></el-form-item><el-form-item label="服务类型" prop="type"><el-select v-model="form.type" style="width:100%"><el-option label="技术指导" value="技术指导"/><el-option label="农机服务" value="农机服务"/><el-option label="灾害防范" value="灾害防范"/></el-select></el-form-item><el-form-item label="作物" prop="crop"><el-input v-model="form.crop"/></el-form-item><el-form-item label="服务区域" prop="regionName"><el-input v-model="form.regionName" placeholder="如 阜阳市或全省"/></el-form-item><el-form-item label="提供单位" prop="provider"><el-input v-model="form.provider"/></el-form-item><el-form-item label="服务内容" prop="content"><el-input v-model="form.content" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="pushVisible" title="定向推送" width="460px"><el-form ref="pushFormRef" :model="pushForm" :rules="pushRules" label-width="90px"><el-form-item label="目标区域" prop="regionName"><el-input v-model="pushForm.regionName" placeholder="填写推送区域"/></el-form-item><el-form-item label="触达数量" prop="count"><el-input-number v-model="pushForm.count" :min="1" :precision="0" style="width:100%"/></el-form-item><el-form-item label="推送说明"><el-input v-model="pushForm.remark" type="textarea" :rows="3" placeholder="填写推送说明"/></el-form-item></el-form><template #footer><el-button @click="pushVisible=false">取消</el-button><el-button type="primary" @click="push">确认推送</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { fetchFarmServices, saveFarmService, publishFarmService, pushFarmService } from '@/api/gpm'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const rows = ref([]); const visible = ref(false); const pushVisible = ref(false); const formRef = ref(); const pushFormRef = ref(); const pushTarget = ref(null); const filters = reactive({ keyword: '', type: '', status: '' }); const form = reactive({ id: '', title: '', type: '技术指导', crop: '小麦', regionName: '', provider: '', content: '' }); const pushForm = reactive({ regionName: '', count: 20, remark: '' }); const formRules = { title: [{ required: true, message: '请输入服务标题', trigger: 'blur' }], type: [{ required: true, message: '请选择服务类型', trigger: 'change' }], crop: [{ required: true, message: '请输入服务作物', trigger: 'blur' }], regionName: [{ required: true, message: '请输入服务区域', trigger: 'blur' }], provider: [{ required: true, message: '请输入提供单位', trigger: 'blur' }], content: [{ required: true, message: '请输入服务内容', trigger: 'blur' }] }; const pushRules = { regionName: [{ required: true, message: '请输入目标区域', trigger: 'blur' }], count: [{ required: true, message: '请输入触达数量', trigger: 'change' }] }
const load = async () => { rows.value = await fetchFarmServices(userStore.role, filters) }
const reset = () => { Object.assign(filters, { keyword: '', type: '', status: '' }); load() }
const openEdit = row => { Object.assign(form, row || { id: '', title: '', type: '技术指导', crop: '小麦', regionName: '', provider: '', content: '' }); formRef.value?.clearValidate(); visible.value = true }
const save = async () => { const valid = await formRef.value?.validate().catch(() => false); if (!valid) return; const result = await saveFarmService({ ...form }); if (!result.success) return ElMessage.error(result.message); visible.value = false; ElMessage.success('农事服务已保存'); load() }
const publish = async row => { const nextStatus = row.status === '已发布' ? '待发布' : '已发布'; try { await ElMessageBox.confirm(`确认${nextStatus === '已发布' ? '发布' : '撤回'}“${row.title}”？`, '状态确认', { type: 'warning' }) } catch { return } const result = await publishFarmService(row.id, nextStatus); if (!result.success) return ElMessage.error(result.message); ElMessage.success(`服务已${nextStatus === '已发布' ? '发布' : '撤回'}`); await load() }
const openPush = row => { pushTarget.value = row; Object.assign(pushForm, { regionName: row.regionName || '', count: 20, remark: '' }); pushFormRef.value?.clearValidate(); pushVisible.value = true }
const push = async () => { const valid = await pushFormRef.value?.validate().catch(() => false); if (!valid || !pushTarget.value) return; const result = await pushFarmService(pushTarget.value.id, { ...pushForm }); if (!result.success) return ElMessage.error(result.message); pushVisible.value = false; ElMessage.success(`已向${pushForm.regionName}推送${pushForm.count}条`); load() }
onMounted(load)
</script>
<style lang="scss" scoped>.gpm-page{gap:12px;overflow:auto}.page-head{display:flex;justify-content:space-between;align-items:flex-start}.eyebrow{color:var(--ah-primary);font-size:11px;letter-spacing:1px;font-weight:700}h2{margin:4px 0;font-size:22px}.page-head p{color:var(--ah-text-secondary);font-size:13px}.filters{display:flex;align-items:center;flex-wrap:wrap}.filters :deep(.el-form-item){margin-bottom:12px;margin-right:12px}</style>